void PrismEditor::toggle(const char* id){p.setValue(id,p.value(id)>.5f?0:1);}
void PrismEditor::attach(){for(int i=0;i<8;++i){attachments[i].reset();auto id=prism::floatIDs[shifted?i+8:i];knobs[i].setName(prism::floatNames[shifted?i+8:i]);knobs[i].setTooltip(knobs[i].getName()+" / Drag to change; Shift-drag for precision; double-click to reset.");attachments[i]=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.state,id,knobs[i]);knobs[i].setDoubleClickReturnValue(true,prism::initial[shifted?i+8:i]);}}
